["Čo je mätúca (confounding) premenná?",["Premenná, ktorá súvisí s nezávislou aj závislou premennou a skresľuje kauzálny záver","Premenná, ktorú meriame ako výsledok","Premenná, ktorú manipulujeme","Premenná bez vplyvu"],"Napr. vzťah predaja zmrzliny a utopení vysvetľuje teplota."],
["Čo je efekt očakávania experimentátora (Rosenthal)?",["Očakávania výskumníka neúmyselne ovplyvnia správanie účastníkov alebo výsledky","Účastníci sa správajú lepšie, keď vedia, že sú sledovaní","Výsledky sa zhoršujú s časom","Experimentátor mení hypotézu po zbere dát"],"Predchádza sa mu dvojito slepým postupom a štandardizáciou."],
["Čo je Hawthornský efekt?",["Zmena správania ľudí len preto, že vedia, že sú pozorovaní","Zlepšenie výkonu vďaka lepšiemu osvetleniu","Skreslenie pri spätnom vybavovaní","Vplyv poradia otázok v dotazníku"],"Pomenovaný podľa výskumov v závode Western Electric v Hawthorne."],
["Ktorá škála merania má skutočný nulový bod?",["Pomerová","Intervalová","Ordinálna","Nominálna"],"Na pomerovej škále má zmysel povedať „dvakrát viac“ (napr. reakčný čas)."],
["Čo je reliabilita typu zhoda posudzovateľov?",["Miera zhody, s akou dvaja nezávislí hodnotitelia posudzujú to isté","Stabilita testu v čase","Súvislosť položiek medzi sebou","Zhoda s kritériom"],"Často sa vyjadruje Cohenovou kappou."],
["Aký je vzťah reliability a validity?",["Reliabilita je nutnou, ale nie postačujúcou podmienkou validity","Validný test môže byť úplne nereliabilný","Sú na sebe nezávislé","Vysoká reliabilita zaručuje validitu"],"Váha, ktorá stále ukazuje o 2 kg viac, je spoľahlivá, ale nie presná (validná)."],
["Čo je debriefing?",["Vysvetlenie skutočného cieľa výskumu účastníkom po skončení, najmä pri klamaní","Úvodný pohovor s účastníkom","Vyhodnotenie dát","Písanie výskumnej správy"],"Je dôležitou súčasťou etiky výskumu."],
["Ktoré metódy patria do kvalitatívneho výskumu?",["Pološtruktúrovaný rozhovor, interpretatívna fenomenologická analýza, zakotvená teória","Experiment, t-test, ANOVA","Štandardizovaný dotazník s Likertovou škálou","Meranie reakčného času"],"Kvalitatívny výskum hľadá porozumenie významom, nie početnosti."],
["Čo je saturácia v kvalitatívnom výskume?",["Bod, keď ďalšie dáta neprinášajú nové témy","Maximálny počet otázok v rozhovore","Úplné vyplnenie dotazníka","Štatistická významnosť"],"Pomáha určiť, kedy ukončiť zber dát."],
["Ktorá chyba pri tvorbe dotazníkových položiek je „dvojhlavňová“ otázka?",["Položka, ktorá sa pýta na dve veci naraz","Položka s dvojitým záporom","Položka, ktorá napovedá odpoveď","Položka s otvorenou odpoveďou"],"Napr. „Ste spokojný so svojou prácou a platom?“ – nevieme, na čo respondent odpovedá."],
["Čo je sklon k sociálne žiaducim odpovediam?",["Tendencia odpovedať tak, aby sa človek ukázal v lepšom svetle","Odpovedanie náhodne","Súhlas s každou položkou","Výber stredných možností"],"Súhlas s každou položkou je acquiescencia; výber stredu je tendencia k stredu."],
["Čo je predregistrácia výskumu?",["Zverejnenie hypotéz, dizajnu a plánu analýz pred zberom dát","Prihlásenie sa na konferenciu","Registrácia účastníkov","Schválenie rozpočtu"],"Znižuje riziko p-hackingu a dodatočného prispôsobovania hypotéz (HARKing)."],
["Čo je metaanalýza?",["Štatistické spojenie výsledkov viacerých štúdií na rovnakú tému","Opis jednej prípadovej štúdie","Kvalitatívny rozhovor","Opakovanie experimentu na tej istej vzorke"],"Výsledkom je odhad priemernej veľkosti efektu."],
["Čo je publikačné skreslenie (publication bias)?",["Signifikantné výsledky sa publikujú častejšie ako nesignifikantné","Publikujú sa len kvalitatívne štúdie","Autori citujú len sami seba","Časopisy odmietajú dlhé články"],"Skresľuje obraz literatúry a nafukuje veľkosti efektov."]
